$('#userName').addEventListener('change',()=>{state.name=$('#userName').value.trim();save();});
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}


const zhArticleData = {"hay": ["干草：每日饮食基础", "为什么应始终提供优质干草。", "<p>应随时提供优质、低粉尘的干草。干草提供粗纤维，并有助于自然磨耗不断生长的臼齿。</p><h3>日常护理</h3><ul><li>每天提供新鲜干草，并清除潮湿或弄脏的干草。</li><li>存放在干燥、通风处，不要将潮湿干草密封保存。</li><li>如果龙猫突然明显减少进食干草，请及时咨询兽医。</li></ul>"], "pellets": ["颗粒饲料与换粮", "不要突然更换食物，并注意检查配方。", "<p>选择适合龙猫且配方稳定的全价饲料，并遵循生产商建议及兽医意见。含有许多甜味成分的彩色混合饲料通常并不合适。</p><h3>重要提示</h3><ul><li>换粮时应缓慢进行，并仔细观察。</li><li>不要经常喂糖果、蜂蜜棒或高糖零食。</li><li>龙猫食欲下降需要认真对待。</li></ul>"], "water": ["新鲜饮水", "每天更换，并仔细检查饮水器具。", "<p>始终提供干净的饮用水。每天换水，并检查水瓶或水碗是否正常、干净且固定牢靠。</p><h3>观察变化</h3><p>饮水量明显变化可能提示健康问题。如果同时出现其他症状或变化持续存在，请咨询兽医。</p>"], "unsafe": ["零食与不适合的食物", "少即是多：避免含糖和潮湿的零食。", "<p>龙猫的消化系统较为敏感。避免高糖、高脂肪和潮湿的食物，以及来源不明的植物或树枝。</p><h3>请注意</h3><ul><li>不要喂巧克力、糖果或人类零食。</li><li>新鲜香草、叶子或树枝是否适合，取决于种类、来源和干燥方式。</li><li>如有疑问，请勿喂食，并向专业人士咨询。</li></ul>"], "temperature": ["高温与室内环境", "测量温度，确保遮阴和空气流通。", "<p>龙猫对高温很敏感。在动物活动高度放置温度计，有助于了解真实室温。应避免阳光直射以及温暖、通风不良的房间。</p><h3>实用预防措施</h3><ul><li>在笼舍附近测量温度，天气炎热时以及傍晚也要检查。</li><li>提供遮阴、安全的空气流通和凉爽的休息处。</li><li>不要使用可能导致动物冻粘或受伤的冰冷物品。</li><li>出现中暑迹象时，立即寻求兽医帮助。</li></ul><p>本应用仅提供参考。实际热负担还取决于湿度、气流、健康状况和行为。</p>"], "housing": ["笼舍与躲藏处", "空间充足、安全、通风良好，并设有多个躲藏点。", "<p>笼舍应宽敞、安全且通风良好，并配有稳固的平台、躲藏处和适当的活动设施。栏杆间距、材料和跳跃高度都应避免造成伤害。</p><h3>定期检查</h3><ul><li>避免锋利边缘、松动的金属丝或有毒材料。</li><li>提供躲藏处和多个安全的平台。</li><li>合理布置设施，避免从高处跌落。</li></ul>"], "dust": ["正确提供沙浴", "使用适合龙猫的浴沙，不要添加浴盐或香料。", "<p>沙浴用于护理毛发。请使用适合龙猫的浴沙，并保持容器清洁、干燥。不要使用有香味、粉尘过多或不适合的浴沙混合物。</p><p>沙浴的时长和频率应根据动物、环境及专业建议来决定。如果龙猫把沙浴当作厕所或浴沙明显变脏，请将其移除。</p>"], "companions": ["社交与合笼", "龙猫是群居动物，需要合适的同伴。", "<p>原则上，不应在没有充分理由的情况下单独饲养龙猫。引入新同伴需要仔细计划，也可能需要较长时间。</p><h3>提前准备</h3><ul><li>请专业人士确认性别，以避免意外繁殖。</li><li>与有经验的兽医讨论新动物的隔离和健康检查。</li><li>规划缓慢且安全的合笼过程，并提供可躲避的空间。</li><li>如果发生激烈打斗，应分开动物并寻求专业帮助。</li></ul>"], "droppings": ["观察粪便与消化", "粪便数量、形态和食欲是重要的日常信号。", "<p>每天简单检查粪便数量和外观是否与平时一致。粪便明显减少或停止排出、拒绝进食、腹部胀大或精神极度萎靡，都可能是紧急情况。</p><p>出现这些变化时不要等待或自行治疗，应尽快联系有龙猫诊疗经验的兽医。</p>"], "weight": ["科学记录体重", "定期称重，并尽量保持相似条件。", "<p>体重记录有助于观察趋势，但不能替代兽医检查。尽量使用同一台秤，并在每天相近的时间称重。也要记录明显的行为变化。</p><h3>何时需要采取行动？</h3><p>原因不明的体重下降、食欲不振或排泄变化，应尽快由兽医检查。本应用不会为你的动物设定医学诊断阈值。</p>"], "vet": ["兽医与紧急症状", "提前寻找合适的诊所，并及时采取行动。", "<p>建议提前寻找有龙猫诊疗经验的兽医，并保存联系方式和急诊信息。龙猫可能会长时间隐藏疾病迹象。</p><h3>需要尽快就医的情况</h3><ul><li>拒绝进食或粪便明显减少。</li><li>呼吸异常、喘气、虚弱或倒下。</li><li>大量流口水、失去平衡或受伤。</li><li>行为突然发生明显变化。</li></ul><p>出现急性或严重症状时，请立即寻求兽医帮助。</p>"], "enrichment": ["安全的活动与玩耍", "提供啃咬、探索、躲藏和跳跃的机会。", "<p>提供安全的啃咬材料、稳固的平台、隧道和躲藏处。定期检查玩具是否有碎片、松动部件、有毒涂层或可能被吞下的小零件。</p><p>活动设施应让动物有选择，并随时可以躲避。观察动物实际喜欢使用什么，不要频繁改变环境。</p>"], "cleaning": ["清洁且减少压力", "每天清理脏污区域，并定期彻底清洁。", "<p>定期清除潮湿或严重脏污的垫料。使用适合动物的清洁用品，必要时彻底冲洗，并让所有物品完全干燥。</p><p>彻底清洁时，应确保动物待在安全的地方，避免不必要的压力。异味也可能提示潮湿区域或健康问题。</p>"], "handling": ["建立信任", "耐心、规律和自愿接触很重要。", "<p>安静地坐在附近，轻声说话，让龙猫自行决定是否靠近。可以伸出手让它闻一闻，避免从上方突然抓取。</p><p>龙猫并不是随时都可以抱的宠物。请尊重它们躲避和表达界限的需要。短暂、积极的互动比强迫接触更好。</p>"]};
const enArticleData = {
'hay':['Hay: the daily foundation','Why good-quality hay should always be available.','<p>Good-quality, low-dust hay should always be available. It provides fibre and supports the natural wear of continuously growing cheek teeth.</p><h3>Everyday care</h3><ul><li>Offer fresh hay and remove damp or soiled hay.</li><li>Store it in a dry, well-ventilated place.</li><li>If hay intake suddenly drops, contact a veterinarian promptly.</li></ul>'],
'pellets':['Pellets and food changes','Avoid sudden diet changes and check the ingredients.','<p>Choose a suitable, consistent complete feed for chinchillas and follow the manufacturer’s guidance and veterinary advice. Colourful mixes with many sweet ingredients are often unsuitable.</p><h3>Important</h3><ul><li>Introduce food changes gradually and monitor your pet.</li><li>Avoid sweets, honey sticks and sugary snacks as routine treats.</li><li>Loss of appetite should always be taken seriously.</li></ul>'],
'water':['Fresh drinking water','Change it daily and check the drinking bottle or bowl.','<p>Always provide clean drinking water. Change it daily and check that the bottle or bowl works properly, is clean and securely positioned.</p><h3>Watch for changes</h3><p>A noticeable change in drinking can indicate a problem. Contact a veterinary practice if other symptoms appear or the change persists.</p>'],
'unsafe':['Treats and unsuitable foods','Less is more: avoid sugary and moist snacks.','<p>Chinchillas have sensitive digestive systems. Avoid sugary, fatty or moist foods, as well as unidentified plants and branches.</p><h3>Please note</h3><ul><li>Do not feed chocolate, sweets or human snack foods.</li><li>Whether fresh herbs, leaves or branches are suitable depends on the species, source and preparation.</li><li>If unsure, do not feed it and ask a knowledgeable professional.</li></ul>'],
'temperature':['Heat and room climate','Measure temperature and provide shade and airflow.','<p>Chinchillas are sensitive to heat. A thermometer placed at the animals’ level helps you monitor the actual room temperature. Avoid direct sunlight and warm, poorly ventilated rooms.</p><h3>Practical prevention</h3><ul><li>Measure temperature near the enclosure, including on warm days and in the evening.</li><li>Provide shade, safe airflow and cool places to retreat.</li><li>Avoid cold objects that could cause sticking or injury.</li><li>Seek veterinary help immediately if heat stress is suspected.</li></ul><p>This app provides general guidance only. Actual heat stress also depends on humidity, airflow, health and behaviour.</p>'],
'housing':['Enclosure and hiding places','Provide a spacious, safe, well-ventilated enclosure with several hiding places.','<p>The enclosure should be spacious, safe and well ventilated, with stable platforms, hiding places and suitable enrichment. Bar spacing, materials and jumping heights should be chosen to prevent injuries.</p><h3>Check regularly</h3><ul><li>Avoid sharp edges, loose wires and toxic materials.</li><li>Provide hiding places and several safe platforms.</li><li>Arrange furnishings to reduce the risk of falls from height.</li></ul>'],
'dust':['Offering a dust bath safely','Use chinchilla-safe bath dust without salts or fragrances.','<p>A dust bath helps maintain the coat. Use bath dust suitable for chinchillas and keep the container clean and dry. Avoid scented, excessively dusty or unsuitable mixtures.</p><p>Frequency and duration should depend on the animal, environment and professional advice. Remove the bath if it is used as a toilet or becomes heavily soiled.</p>'],
'companions':['Social needs and introductions','Chinchillas are social animals and need suitable companionship.','<p>As a rule, chinchillas should not be kept alone without a good reason. Introducing a companion needs careful planning and may take time.</p><h3>Prepare in advance</h3><ul><li>Confirm the animals’ sexes to prevent unexpected breeding.</li><li>Discuss quarantine and health checks for new animals with an experienced veterinarian.</li><li>Plan a gradual, safe introduction with places to retreat.</li><li>If serious fighting occurs, separate the animals and seek expert help.</li></ul>'],
'droppings':['Monitoring droppings and digestion','Dropping quantity, shape and appetite are useful daily signals.','<p>Check each day whether the amount and appearance of droppings seem normal. A major reduction or absence of droppings, refusal to eat, a swollen abdomen or severe lethargy may be urgent.</p><p>Do not wait or try to treat these changes yourself. Contact a veterinarian experienced with chinchillas promptly.</p>'],
'weight':['Keeping useful weight records','Weigh regularly under similar conditions.','<p>A weight diary can reveal trends but does not replace a veterinary examination. Use the same scale where possible and weigh at a similar time of day. Note any unusual behaviour as well.</p><h3>When to act</h3><p>Unexplained weight loss, loss of appetite or changes in droppings should be checked by a veterinarian promptly. This app does not set medical thresholds for your pet.</p>'],
'vet':['Veterinary care and emergency signs','Find an experienced practice in advance and act promptly.','<p>Find a veterinary practice experienced with chinchillas before an emergency and save its contact and out-of-hours details. Chinchillas can hide signs of illness for a long time.</p><h3>Seek urgent advice for</h3><ul><li>Refusal to eat or a marked drop in droppings.</li><li>Unusual breathing, panting, weakness or collapse.</li><li>Heavy drooling, balance problems or injuries.</li><li>Sudden, significant behaviour changes.</li></ul><p>For acute or severe symptoms, seek veterinary help immediately.</p>'],
'enrichment':['Safe enrichment and play','Allow opportunities to chew, explore, hide and jump.','<p>Provide safe chew materials, stable platforms, tunnels and hiding places. Regularly check toys for splinters, loose parts, toxic coatings or small pieces that could be swallowed.</p><p>Enrichment should offer choice and always allow your chinchilla to retreat. Observe what your pet actually uses instead of constantly changing the setup.</p>'],
'cleaning':['Cleaning without unnecessary stress','Remove soiled areas daily and clean thoroughly on a regular basis.','<p>Regularly remove damp or heavily soiled bedding. Use animal-safe cleaning products, rinse carefully when needed and allow everything to dry completely.</p><p>During a full clean, keep the animals somewhere safe and avoid unnecessary stress. Unusual odours can indicate damp areas or possible health issues.</p>'],
'handling':['Building trust','Patience, routine and voluntary contact matter.','<p>Sit quietly nearby, speak softly and let your chinchilla decide whether to approach. Offer your hand to sniff and avoid grabbing from above.</p><p>Chinchillas are not pets that always want to be cuddled. Respect their need to retreat and their individual boundaries. Short, positive interactions are better than forced contact.</p>']
};
articles.push(
{id:'furcare',icon:'🪮',cat:'housing',title:'Fellpflege und Sandbad',summary:'Warum Bürsten meist nicht zur normalen Pflege gehört.',body:`<p>Chinchillas pflegen ihr dichtes Fell normalerweise selbst durch geeignete Sandbäder. Das Fell sollte nicht routinemäßig gebürstet oder gebadet werden, weil dies Stress und Fellschäden verursachen kann.</p><h3>Darauf achten</h3><ul><li>Nur geeigneten Chinchillasand verwenden, keine Duftstoffe oder Badesalze.</li><li>Sandbad sauber und trocken halten und bei Verschmutzung entfernen.</li><li>Verfilzungen, kahle Stellen, Schuppen oder anhaltendes Kratzen tierärztlich abklären lassen.</li><li>Nicht mit Wasser baden, außer eine Tierarztpraxis weist dies ausdrücklich an.</li></ul>`},
{id:'accessories',icon:'🪵',cat:'housing',title:'Sicheres Käfigzubehör',summary:'Holz, Verstecke und Plattformen bewusst auswählen.',body:`<p>Geeignet sind stabile, ungiftige und unbehandelte Materialien sowie mehrere Verstecke und sichere Plattformen. Alle Ebenen müssen so geplant sein, dass tiefe Stürze vermieden werden.</p><h3>Checkliste</h3><ul><li>Stabile Häuser mit mindestens zwei Ausgängen sind oft praktisch.</li><li>Keine Laufräder mit Gittersprossen oder gefährlich kleinen Durchmessern; bei Laufrädern auf chinchillageeignete, geschlossene Lauffläche und passende Größe achten.</li><li>Keine weichen Kunststoffe, Schaumstoffe, giftigen Lacke oder leicht verschluckbaren Kleinteile.</li><li>Regelmäßig auf Splitter, lockere Schrauben und scharfe Kanten prüfen.</li></ul>`},
{id:'fur',icon:'✨',cat:'health',title:'Fell, Haut und Warnzeichen',summary:'Was normales Fell ist und wann Hilfe nötig wird.',body:`<p>Ein dichtes Fell ist normal. Achte auf kahle Stellen, Rötungen, Schuppen, ungewöhnlichen Geruch, starkes Kratzen oder plötzlich veränderte Fellstruktur. Stress, Hautprobleme und Pilzerkrankungen können ähnlich aussehen.</p><p>Verwende keine Cremes oder Medikamente auf eigene Faust. Bei Hautveränderungen, Schmerzen oder deutlicher Verhaltensänderung eine chinchilla-erfahrene Tierarztpraxis kontaktieren.</p>`}
);
function localizedArticle(a){if(state.lang==='zh'&&zhArticleData[a.id]){const z=zhArticleData[a.id];return {...a,title:z[0],summary:z[1],body:z[2]};}if(state.lang==='en'&&enArticleData[a.id]){const e=enArticleData[a.id];return {...a,title:e[0],summary:e[1],body:e[2]};}return a;}
function renderAll(){document.body.classList.toggle('dark',!!state.dark);$('#themeBtn').textContent=state.dark?'☾':'☼';$('#userName').value=state.name||'';renderDate();renderRoutine();renderAnimals();renderClimate();renderPlanner();renderArticles();}
function init(){if(!state.routineDate||state.routineDate!==today()){state.routineDate=today();state.routine={};}applyLanguage();renderAll();go('home');}

